# Provider config. No credentials live here — auth comes from the ambient
# AWS CLI profile (AWS_PROFILE=dataq-deploy, a scoped IAM user; NOT root — see
# README.md's IAM bootstrap section) or AWS_* env vars.

provider "aws" {
  region = var.aws_region

  default_tags {
    tags = local.common_tags
  }
}

provider "random" {}
# DataQ APP infra — AWS, OpenTofu / provider pins.
#
# This stack provisions a SECOND, parallel deployment of DataQ's application
# resources (ECS Fargate api + worker + frontend + migrate task + RDS +
# ElastiCache + Cognito) into a fresh, dedicated AWS account. Unlike the Azure
# stack (deploy/terraform/azure/), nothing here is shared with another stack —
# the account exists only for this deployment, so there is no "ensure it
# exists, never destroy it" pattern for a resource group equivalent.
#
# Local state backend — state is gitignored, never committed (it contains the
# generated Postgres password + other secret values). Pin providers; do not
# float.
#
# The CLI is OpenTofu (`tofu`), not Terraform — ADR 0024 amendment
# (2026-07-27), same rationale as the Azure stack: Terraform has been
# BUSL-1.1 since v1.6, the last source-available binary touching an
# MIT-distributed project. Providers resolve from registry.opentofu.org.

terraform {
  required_version = ">= 1.9"

  backend "local" {
    path = "terraform.tfstate"
  }

  # State encryption (mirrors the Azure stack's #1087 decision — local state
  # holds the generated Postgres/ElastiCache passwords). A wrong/missing
  # passphrase fails closed ("cipher: message authentication failed") without
  # corrupting the file; losing the passphrase makes the state permanently
  # unreadable, so keep a second copy off this machine (see README.md).
  encryption {
    key_provider "pbkdf2" "local" {
      passphrase = var.state_encryption_passphrase
    }
    method "aes_gcm" "primary" {
      keys = key_provider.pbkdf2.local
    }
    state {
      method = method.aes_gcm.primary
    }
    plan {
      method = method.aes_gcm.primary
    }
  }

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.6"
    }
  }
}
# Networking: one VPC, 2 public subnets across 2 AZs, an Internet Gateway, no
# NAT Gateway (decision: public-subnets-no-NAT — saves ~$33/mo; ECS tasks get
# no public IP/inbound exposure since security groups gate everything, only
# the ALB->frontend path is internet-reachable). RDS and ElastiCache also sit
# in these public subnets with no public IP/endpoint access, for the same
# reason the Azure stack doesn't stand up a separate private-subnet tier for
# a single-environment deployment. Documented MVP tradeoff — see the approved
# deployment plan; harden to private subnets + NAT/VPC endpoints later if a
# real compliance/traffic need justifies the cost.

data "aws_availability_zones" "available" {
  state = "available"
}

resource "random_string" "suffix" {
  length  = 6
  lower   = true
  upper   = false
  numeric = true
  special = false
}

locals {
  # All DataQ-APP-AWS resources carry this tag set so they're trivially
  # distinguishable from anything else that might land in this account later.
  common_tags = {
    Project = "dataq"
    Managed = "terraform"
    Purpose = "dataq-app-aws"
  }

  az_count     = 2
  azs          = slice(data.aws_availability_zones.available.names, 0, local.az_count)
  vpc_cidr     = "10.20.0.0/16"
  public_cidrs = [for i in range(local.az_count) : cidrsubnet(local.vpc_cidr, 4, i)]
}

resource "aws_vpc" "app" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = { Name = "dataq-app-vpc" }
}

resource "aws_internet_gateway" "app" {
  vpc_id = aws_vpc.app.id

  tags = { Name = "dataq-app-igw" }
}

resource "aws_subnet" "public" {
  count                   = local.az_count
  vpc_id                  = aws_vpc.app.id
  cidr_block              = local.public_cidrs[count.index]
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = true

  tags = { Name = "dataq-app-public-${count.index}" }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.app.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.app.id
  }

  tags = { Name = "dataq-app-public-rt" }
}

resource "aws_route_table_association" "public" {
  count          = local.az_count
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

data "aws_caller_identity" "current" {}
# Non-secret configuration. Defaults are wired for the AWS parallel-deployment
# bring-up. Override in terraform.tfvars (gitignored) — see
# terraform.tfvars.example. Two required inputs have no default and will hang
# OpenTofu on stdin if missing — always pass -input=false.

variable "aws_region" {
  description = "AWS region for every resource in this stack."
  type        = string
  default     = "us-east-2"
}

# ── Database ──────────────────────────────────────────────────────────────

variable "app_db_name" {
  description = "The app's database name."
  type        = string
  default     = "dataq"
}

variable "app_db_user" {
  description = "Least-privilege role the app connects as."
  type        = string
  default     = "dataq_app"
}

variable "app_db_password" {
  description = "Password for app_db_user. Pass at apply: TF_VAR_app_db_password=... . Injected into Secrets Manager as an infra-owned secret; never committed."
  type        = string
  sensitive   = true
}

# ── Images (GHCR — ADR 0023, cloud-agnostic) ────────────────────────────────

variable "backend_image_repo" {
  description = "GHCR backend image repository (public package, anonymous pull)."
  type        = string
  default     = "ghcr.io/theurgicduke771/dataq-backend"
}

variable "frontend_image_repo" {
  description = "GHCR frontend (nginx SPA) image repository — one generic runtime-configured image (ADR 0028)."
  type        = string
  default     = "ghcr.io/theurgicduke771/dataq-frontend"
}

variable "image_tag" {
  description = "Backend image tag to deploy. Immutable tag in prod. The live image is rolled out-of-band by CI (ignore_changes on the task definition's container image), so this is only the create-time default."
  type        = string
  default     = "v10"
}

variable "frontend_image_tag" {
  description = "Frontend image tag to deploy. Same out-of-band rollout note as image_tag."
  type        = string
  default     = "v2"
}

# ── App config (non-secret) ──────────────────────────────────────────────

variable "environment" {
  description = "ENVIRONMENT value the backend Settings read."
  type        = string
  default     = "prod"
}

variable "workspace_admin_emails" {
  description = "Comma-separated workspace-admin allowlist (WORKSPACE_ADMIN_EMAILS)."
  type        = string
  default     = ""
}

variable "email_username" {
  description = "SMTP login / sender for the email alert channel. Empty = channel off."
  type        = string
  default     = ""
}

variable "email_from" {
  description = "From: address for email alerts (defaults to email_username when empty)."
  type        = string
  default     = ""
}

variable "email_to" {
  description = "Comma-separated recipients for email alerts. Empty = email channel off."
  type        = string
  default     = ""
}

# ── Secrets (AWS Secrets Manager — SECRET_STORE=aws_secrets_manager) ───────

variable "aws_secrets_manager_prefix" {
  description = "Namespace prefix for datasource-credential secrets the app manages at runtime (AWS_SECRETS_MANAGER_PREFIX). Distinct from the infra-owned bootstrap secrets (DB URL etc.), which live under a separate dataq-app-infra/ prefix this stack owns directly."
  type        = string
  default     = "dataq"
}

# ── Cognito (generic OIDC — core/auth.py OidcBearerScheme) ─────────────────

variable "cognito_callback_path" {
  description = "Path appended to the frontend URL for the OIDC redirect callback (oidc-client-ts default)."
  type        = string
  default     = "/auth/callback"
}

# ── CI deploy (GitHub OIDC) ─────────────────────────────────────────────────

variable "github_repo" {
  description = "owner/repo the Deploy workflow runs from (federated-credential subject)."
  type        = string
  default     = "TheurgicDuke771/DataQ"
}

variable "github_environment" {
  description = "GitHub environment the federated credential is scoped to."
  type        = string
  default     = "production"
}

# ── State encryption (OpenTofu) ─────────────────────────────────────────────

variable "state_encryption_passphrase" {
  description = <<-DESC
    Passphrase for OpenTofu state encryption (versions.tf `encryption` block).

    Supplied from the gitignored terraform.tfvars. This is a DATA-AT-REST KEY,
    not a credential: it cannot be revoked and it cannot be re-minted. Losing
    it means terraform.tfstate is unrecoverable — keep a second copy off this
    machine. See README.md.
  DESC
  type        = string
  sensitive   = true
}

# ── Sizing / retention ───────────────────────────────────────────────────

variable "log_retention_days" {
  description = "CloudWatch Logs retention for every DataQ log group."
  type        = number
  default     = 30
}

# ECS Fargate — api (internal, Cloud Map DNS), worker (Celery + embedded
# beat, min=max=1 desired count — mirrors the Azure Container App's
# min_replicas=1 rationale: it can't scale to zero because it runs beat), and
# frontend (public via the ALB). All three run images from GHCR (public,
# anonymous pull — ADR 0023), same as the Azure stack.

resource "aws_ecs_cluster" "app" {
  name = "dataq-app"

  tags = { Name = "dataq-app" }
}

# One shared security group for every ECS task: self-referencing ingress lets
# api/worker/frontend talk to each other (and to Redis/RDS, which have their
# own SGs allowing traffic FROM this one), plus a narrow allow from the ALB
# SG for the frontend's published port.
resource "aws_security_group" "ecs_tasks" {
  name        = "dataq-app-ecs-tasks"
  description = "DataQ ECS tasks — internal task-to-task traffic + ALB->frontend"
  vpc_id      = aws_vpc.app.id

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = { Name = "dataq-app-ecs-tasks" }
}

resource "aws_security_group_rule" "ecs_tasks_self_ingress" {
  # Narrower than "every port" on purpose: the only task-to-task call within
  # this security group is frontend -> api on 8000 (Cloud Map DNS). worker
  # and frontend serve nothing another task calls, so opening the full
  # 0-65535 range would grant blast-radius no actual traffic pattern needs.
  type                     = "ingress"
  from_port                = 8000
  to_port                  = 8000
  protocol                 = "tcp"
  security_group_id        = aws_security_group.ecs_tasks.id
  source_security_group_id = aws_security_group.ecs_tasks.id
}

resource "aws_security_group_rule" "ecs_tasks_from_alb" {
  type                     = "ingress"
  from_port                = 8080
  to_port                  = 8080
  protocol                 = "tcp"
  security_group_id        = aws_security_group.ecs_tasks.id
  source_security_group_id = aws_security_group.alb.id
}

# Cloud Map private DNS namespace — how the frontend reaches the api
# internally (DATAQ_API_UPSTREAM=http://api.dataq.local:8000, alb.tf's
# local.api_internal_url), the same role the Azure environment's
# `.internal.<domain>` FQDN plays there.
resource "aws_service_discovery_private_dns_namespace" "app" {
  name = "dataq.local"
  vpc  = aws_vpc.app.id
}

resource "aws_service_discovery_service" "api" {
  name = "api"

  dns_config {
    namespace_id = aws_service_discovery_private_dns_namespace.app.id
    dns_records {
      type = "A"
      ttl  = 10
    }
  }

  health_check_custom_config {
    failure_threshold = 1
  }
}

locals {
  backend_image  = "${var.backend_image_repo}:${var.image_tag}"
  frontend_image = "${var.frontend_image_repo}:${var.frontend_image_tag}"

  # Non-secret env, shared by api + worker — mirrors containerapps.tf's
  # local.app_env, with AWS-shaped values in place of the Azure ones.
  app_env = [
    { name = "ENVIRONMENT", value = var.environment },
    { name = "LOG_LEVEL", value = "INFO" },
    { name = "SAMPLE_FAILURES_RETENTION_DAYS", value = "30" },
    # Runtime SecretStore -> AWS Secrets Manager via the ECS task role (no
    # bootstrap credential to hold — same "no credential at all" posture the
    # Azure UAMI + Key Vault pairing has).
    { name = "SECRET_STORE", value = "aws_secrets_manager" },
    { name = "AWS_SECRETS_MANAGER_PREFIX", value = "${var.aws_secrets_manager_prefix}/" },
    # Real auth in prod (AUTH_DEV_BYPASS=false) via the generic OIDC path
    # (ADR 0026 amendment) — NOT the Azure fields, which stay unset.
    { name = "AUTH_DEV_BYPASS", value = "false" },
    { name = "OIDC_ISSUER", value = local.cognito_issuer },
    { name = "OIDC_AUDIENCE", value = aws_cognito_user_pool_client.spa.id },
    { name = "WORKSPACE_ADMIN_EMAILS", value = var.workspace_admin_emails },
    # Rate-limit per-IP keying (ADR 0035). ALB -> ECS is a single hop, so the
    # trusted XFF depth is 1 here — NOT the Azure stack's 3 (public-envoy +
    # nginx + internal-envoy chain, which doesn't exist on this topology).
    # Confirm against one logged live XFF post-deploy, same as the Azure note.
    { name = "RATE_LIMIT_XFF_TRUSTED_HOPS", value = "1" },
    { name = "CORS_ALLOW_ORIGINS", value = "" },
    { name = "PUBLIC_BASE_URL", value = local.frontend_url },
    { name = "ADF_WEBHOOK_SECRET_NAME", value = "adf-webhook-secret" },
    { name = "AIRFLOW_WEBHOOK_SECRET_NAME", value = "airflow-webhook-secret" },
    { name = "DBT_WEBHOOK_SECRET_NAME", value = "dbt-webhook-secret" },
    { name = "SLACK_WEBHOOK_SECRET_NAME", value = "channel-slack-webhook" },
    { name = "EMAIL_SMTP_HOST", value = "smtp.gmail.com" },
    { name = "EMAIL_SMTP_PORT", value = "587" },
    { name = "EMAIL_PASSWORD_SECRET_NAME", value = "channel-email-password" },
    { name = "EMAIL_USERNAME", value = var.email_username },
    { name = "EMAIL_FROM", value = var.email_from },
    { name = "EMAIL_TO", value = var.email_to },
  ]

  worker_env = concat(local.app_env, [
    { name = "WAREHOUSE_LINEAGE_ENABLED", value = "true" },
  ])

  # Boot-critical secrets, injected via the task definition's `secrets` block
  # (execution-role-read from the infra-owned Secrets Manager entries) —
  # mirrors the Azure stack's inline-Container-App-secret pattern; same
  # reasoning (decouple first-revision activation from any IAM-propagation
  # delay on the app's OWN Secrets Manager grant).
  boot_secrets = [
    { name = "DATABASE_URL", valueFrom = aws_secretsmanager_secret.database_url.arn },
    { name = "REDIS_URL", valueFrom = aws_secretsmanager_secret.redis_url.arn },
  ]
}

# ── API (internal, Cloud Map) ────────────────────────────────────────────

resource "aws_ecs_task_definition" "api" {
  family                   = "dataq-app-api"
  requires_compatibilities = ["FARGATE"]
  network_mode             = "awsvpc"
  cpu                      = 512
  memory                   = 1024
  execution_role_arn       = aws_iam_role.ecs_task_execution.arn
  task_role_arn            = aws_iam_role.ecs_task_api.arn

  container_definitions = jsonencode([
    {
      name         = "api"
      image        = local.backend_image
      essential    = true
      portMappings = [{ containerPort = 8000, protocol = "tcp" }]
      environment  = local.app_env
      secrets      = local.boot_secrets
      logConfiguration = {
        logDriver = "awslogs"
        options = {
          "awslogs-group"         = aws_cloudwatch_log_group.api.name
          "awslogs-region"        = var.aws_region
          "awslogs-stream-prefix" = "api"
        }
      }
    }
  ])

  # CI rolls the live image out-of-band (new task-def revision via
  # `aws ecs register-task-definition` + `update-service`) — mirrors the
  # Azure stack's `ignore_changes` on the container image, same reasoning.
  lifecycle {
    ignore_changes = [container_definitions]
  }

  tags = { Name = "dataq-app-api" }
}

resource "aws_ecs_service" "api" {
  name            = "dataq-app-api"
  cluster         = aws_ecs_cluster.app.id
  task_definition = aws_ecs_task_definition.api.arn
  desired_count   = 1
  launch_type     = "FARGATE"

  network_configuration {
    subnets          = aws_subnet.public[*].id
    security_groups  = [aws_security_group.ecs_tasks.id]
    assign_public_ip = true # no NAT — see main.tf's decision note
  }

  service_registries {
    registry_arn = aws_service_discovery_service.api.arn
  }

  lifecycle {
    ignore_changes = [task_definition]
  }
}

# ── Worker (Celery worker + embedded beat) ──────────────────────────────

resource "aws_ecs_task_definition" "worker" {
  family                   = "dataq-app-worker"
  requires_compatibilities = ["FARGATE"]
  network_mode             = "awsvpc"
  cpu                      = 1024
  memory                   = 2048
  execution_role_arn       = aws_iam_role.ecs_task_execution.arn
  task_role_arn            = aws_iam_role.ecs_task_worker.arn

  container_definitions = jsonencode([
    {
      name        = "worker"
      image       = local.backend_image
      essential   = true
      command     = ["celery", "-A", "backend.app.worker.celery_app", "worker", "-B", "--loglevel=INFO"]
      environment = local.worker_env
      secrets     = local.boot_secrets
      logConfiguration = {
        logDriver = "awslogs"
        options = {
          "awslogs-group"         = aws_cloudwatch_log_group.worker.name
          "awslogs-region"        = var.aws_region
          "awslogs-stream-prefix" = "worker"
        }
      }
    }
  ])

  lifecycle {
    ignore_changes = [container_definitions]
  }

  tags = { Name = "dataq-app-worker" }
}

resource "aws_ecs_service" "worker" {
  name            = "dataq-app-worker"
  cluster         = aws_ecs_cluster.app.id
  task_definition = aws_ecs_task_definition.worker.arn
  # Cannot scale to zero — runs embedded celery-beat (schedule dispatcher +
  # orchestration polling), same as the Azure Container App's min_replicas=1.
  desired_count = 1
  launch_type   = "FARGATE"

  network_configuration {
    subnets          = aws_subnet.public[*].id
    security_groups  = [aws_security_group.ecs_tasks.id]
    assign_public_ip = true
  }

  lifecycle {
    ignore_changes = [task_definition]
  }
}

# ── Frontend (nginx SPA, sole public surface) ───────────────────────────

resource "aws_ecs_task_definition" "frontend" {
  family                   = "dataq-app-frontend"
  requires_compatibilities = ["FARGATE"]
  network_mode             = "awsvpc"
  cpu                      = 256
  memory                   = 512
  execution_role_arn       = aws_iam_role.ecs_task_execution.arn

  container_definitions = jsonencode([
    {
      name         = "frontend"
      image        = local.frontend_image
      essential    = true
      portMappings = [{ containerPort = 8080, protocol = "tcp" }]
      environment = [
        { name = "DATAQ_API_UPSTREAM", value = local.api_internal_url },
        { name = "DATAQ_AUTH_MODE", value = "oidc" },
        { name = "DATAQ_AUTH_AUTHORITY", value = local.cognito_issuer },
        { name = "DATAQ_AUTH_CLIENT_ID", value = aws_cognito_user_pool_client.spa.id },
      ]
      logConfiguration = {
        logDriver = "awslogs"
        options = {
          "awslogs-group"         = aws_cloudwatch_log_group.frontend.name
          "awslogs-region"        = var.aws_region
          "awslogs-stream-prefix" = "frontend"
        }
      }
    }
  ])

  lifecycle {
    ignore_changes = [container_definitions]
  }

  tags = { Name = "dataq-app-frontend" }
}

resource "aws_ecs_service" "frontend" {
  name            = "dataq-app-frontend"
  cluster         = aws_ecs_cluster.app.id
  task_definition = aws_ecs_task_definition.frontend.arn
  desired_count   = 1
  launch_type     = "FARGATE"

  network_configuration {
    subnets          = aws_subnet.public[*].id
    security_groups  = [aws_security_group.ecs_tasks.id]
    assign_public_ip = true
  }

  load_balancer {
    target_group_arn = aws_lb_target_group.frontend.arn
    container_name   = "frontend"
    container_port   = 8080
  }

  lifecycle {
    ignore_changes = [task_definition]
  }

  depends_on = [aws_lb_listener.http]
}

# Secrets Manager has two distinct owners, matching the Key Vault split on the
# Azure stack (boot-critical secrets are inline Container App secrets there,
# NOT Key Vault references — same reasoning applies here):
#
#   - Infra-owned bootstrap secrets (DATABASE_URL, REDIS_URL) — created by
#     THIS Terraform stack, referenced directly by ARN in each ECS task
#     definition's `secrets` block. Under `dataq-app-infra/`.
#   - App-owned datasource-credential secrets — written by the app itself at
#     runtime via `AwsSecretsManagerStore` (SECRET_STORE=aws_secrets_manager,
#     backend/app/core/secrets.py), under `var.aws_secrets_manager_prefix`
#     ("dataq/" by default). This stack only grants the IAM policy; it never
#     creates or reads these values.

resource "aws_secretsmanager_secret" "database_url" {
  name = "dataq-app-infra/database-url"
}

resource "aws_secretsmanager_secret_version" "database_url" {
  secret_id     = aws_secretsmanager_secret.database_url.id
  secret_string = local.database_url
}

resource "aws_secretsmanager_secret" "redis_url" {
  name = "dataq-app-infra/redis-url"
}

resource "aws_secretsmanager_secret_version" "redis_url" {
  secret_id     = aws_secretsmanager_secret.redis_url.id
  secret_string = local.redis_url
}

# The app's own runtime grant: get/put/create/delete/list on everything under
# its prefix, plus ListSecrets (unavoidably unscoped — the List action family
# has no resource-level restriction in Secrets Manager; AwsSecretsManagerStore
# narrows this itself with a strict client-side prefix check — see
# backend/app/core/secrets.py's list_secrets docstring).
data "aws_iam_policy_document" "app_secrets_rw" {
  statement {
    sid = "AppSecretsReadWrite"
    actions = [
      "secretsmanager:GetSecretValue",
      "secretsmanager:PutSecretValue",
      "secretsmanager:CreateSecret",
      "secretsmanager:DeleteSecret",
    ]
    resources = [
      "arn:aws:secretsmanager:${var.aws_region}:${data.aws_caller_identity.current.account_id}:secret:${var.aws_secrets_manager_prefix}/*"
    ]
  }
  statement {
    sid       = "AppSecretsList"
    actions   = ["secretsmanager:ListSecrets"]
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "api_app_secrets" {
  name   = "dataq-app-secrets-rw"
  role   = aws_iam_role.ecs_task_api.id
  policy = data.aws_iam_policy_document.app_secrets_rw.json
}

resource "aws_iam_role_policy" "worker_app_secrets" {
  name   = "dataq-app-secrets-rw"
  role   = aws_iam_role.ecs_task_worker.id
  policy = data.aws_iam_policy_document.app_secrets_rw.json
}

# Read-only grant on the infra-owned bootstrap secrets, for the ECS task
# EXECUTION role — this is what actually injects them into the container via
# the task definition's `secrets` block (distinct from the task role above,
# which is the app's own runtime identity).
data "aws_iam_policy_document" "execution_infra_secrets_read" {
  statement {
    actions = ["secretsmanager:GetSecretValue"]
    resources = [
      aws_secretsmanager_secret.database_url.arn,
      aws_secretsmanager_secret.redis_url.arn,
    ]
  }
}

resource "aws_iam_role_policy" "execution_infra_secrets_read" {
